"""Plain-language legal glossary for the Jargon Decoder.

Tooltips are grounded only in these entries (entries with no aliases are searchable but not highlighted,
because words like "plaintiff" appear in almost every sentence): the AI never writes or edits definitions.
Definitions explain what a word means, never what anyone should do. Entries are written
in neutral, plain English from commonly published legal glossaries and should be
reviewed by a legal professional before production use.
"""

GLOSSARY: list[dict] = [
    # ---- civil procedure ----------------------------------------------------
    {"term": "Plaint", "alias": ["plaint"], "def": "The written complaint that starts a civil case. It sets out what the plaintiff claims and what they ask the court for."},
    {"term": "Plaintiff", "alias": [], "def": "The person or business that starts a civil case."},
    {"term": "Defendant", "alias": [], "def": "The person or business a civil case is brought against."},
    {"term": "Instituted", "alias": ["instituted"], "def": "Formally started or filed in court."},
    {"term": "Written statement", "alias": ["written statement"], "def": "The defendant's formal written reply to the plaint."},
    {"term": "Replication", "alias": ["replication"], "def": "The plaintiff's reply to new points raised in the written statement."},
    {"term": "Rejoinder", "alias": ["rejoinder"], "def": "A reply to the other side's response."},
    {"term": "Counter-claim", "alias": ["counter-claim", "counterclaim"], "def": "A claim the defendant makes against the plaintiff within the same case."},
    {"term": "Summons", "alias": ["summons"], "def": "A court document telling a person that a case has been filed against them and that they must respond or appear."},
    {"term": "Process server", "alias": ["process server"], "def": "A court official who delivers summons and notices to the parties."},
    {"term": "Legal notice", "alias": ["legal notice"], "def": "A formal letter sent before a case is filed, telling the other side about a claim or demand."},
    {"term": "Ex parte", "alias": ["ex parte"], "def": "Done or decided after hearing only one side, without the other side present."},
    {"term": "Ad-interim", "alias": ["ad-interim", "ad interim"], "def": "A short-term order that lasts only until the court hears the matter more fully."},
    {"term": "Interim injunction", "alias": ["interim injunction"], "def": "A temporary court order telling someone to do, or stop doing, something while the case continues."},
    {"term": "Injunction", "alias": ["injunction"], "def": "A court order telling someone to do, or not to do, a particular act."},
    {"term": "Stay", "alias": ["stay order"], "def": "A court order that temporarily stops a proceeding or the effect of another order."},
    {"term": "Status quo", "alias": ["status quo"], "def": "The existing state of affairs, which a court may order the parties to keep unchanged for now."},
    {"term": "Interlocutory application (IA)", "alias": ["IA", "interlocutory application"], "def": "A request made to the court during a case, before the final decision."},
    {"term": "Affidavit", "alias": ["affidavit", "affidavits"], "def": "A written statement of facts that the person swears is true."},
    {"term": "Deponent", "alias": ["deponent"], "def": "The person who makes and signs an affidavit."},
    {"term": "Admission/denial of documents", "alias": ["admission/denial"], "def": "The stage where each side states which of the other side's documents it accepts and which it disputes."},
    {"term": "Framing of issues", "alias": ["issues are framed", "issues framed", "framing of issues"], "def": "The court's written list of the specific questions of fact and law the case must decide."},
    {"term": "Mediation", "alias": ["mediation"], "def": "A process where a neutral person helps the parties try to reach a settlement."},
    {"term": "Lok Adalat", "alias": ["lok adalat"], "def": "A forum where disputes are settled by agreement with the help of conciliators."},
    {"term": "Local Commissioner", "alias": ["local commissioner", "commissioner"], "def": "A person the court appoints to carry out a task for it, such as recording evidence."},
    {"term": "Examination-in-chief", "alias": ["examination-in-chief", "examination in chief"], "def": "Questioning of a witness by the side that called them."},
    {"term": "Cross-examination", "alias": ["cross-examination", "cross examination"], "def": "Questioning of a witness by the opposing side."},
    {"term": "PW-1", "alias": ["PW-1", "PW1"], "def": "Short for \"Plaintiff (or Prosecution) Witness No. 1\", the first witness called by that side."},
    {"term": "Decree", "alias": ["decree"], "def": "The formal statement of the court's final decision in a civil case."},
    {"term": "Execution", "alias": ["execution petition"], "def": "The process of enforcing a court's decree or order."},
    {"term": "Locus standi", "alias": ["locus standi"], "def": "The right of a person to bring a particular case before the court."},
    {"term": "Certiorari", "alias": ["certiorari"], "def": "A writ through which a higher court reviews the decision of a lower court or authority."},
    {"term": "Mandamus", "alias": ["mandamus"], "def": "A writ directing a public authority to perform a duty it is required to perform."},
    {"term": "Habeas corpus", "alias": ["habeas corpus"], "def": "A writ asking that a person held in custody be brought before the court."},
    {"term": "Writ", "alias": ["writ petition", "writ"], "def": "A formal written order issued by a High Court or the Supreme Court."},
    {"term": "Res judicata", "alias": ["res judicata"], "def": "The principle that a matter already finally decided between the same parties cannot be tried again."},
    {"term": "Sub judice", "alias": ["sub judice"], "def": "Under consideration by a court and not yet decided."},
    {"term": "Prima facie", "alias": ["prima facie"], "def": "At first sight; based on a first look at the material."},
    {"term": "Caveat", "alias": ["caveat"], "def": "A request that the court not pass an order in a matter without first hearing the person who filed it."},
    {"term": "Vakalatnama", "alias": ["vakalatnama"], "def": "A document by which a party authorises an advocate to appear for them."},
    {"term": "Adjournment", "alias": ["adjourned", "adjournment"], "def": "Postponement of a hearing to a later date."},
    {"term": "Limitation", "alias": ["limitation period", "period of limitation"], "def": "The time limit set by law within which a case must be filed."},
    {"term": "Condonation of delay", "alias": ["condonation of delay"], "def": "A court's acceptance of a filing made after the time limit."},
    {"term": "Maintainability", "alias": ["maintainability", "maintainable"], "def": "Whether a case can legally be heard by that court or tribunal at all."},
    {"term": "Pendente lite", "alias": ["pendente lite", "pendency of the suit"], "def": "While the case is pending."},
    {"term": "Suo motu", "alias": ["suo motu"], "def": "Done by the court on its own, without a request from a party."},
    {"term": "Inter alia", "alias": ["inter alia"], "def": "Among other things."},
    {"term": "Amicus curiae", "alias": ["amicus curiae"], "def": "A person who assists the court on a point, without being a party to the case."},
    {"term": "Show cause notice", "alias": ["show cause notice", "show cause"], "def": "A notice asking a person to explain why a particular action should not be taken."},
    {"term": "Contempt of court", "alias": ["contempt of court", "contempt"], "def": "Disobeying a court order or disrespecting the court's authority."},
    # ---- criminal procedure -------------------------------------------------
    {"term": "FIR", "alias": ["FIR", "first information report"], "def": "First Information Report: the police's written record of information about a cognizable offence."},
    {"term": "Cognizable offence", "alias": ["cognizable"], "def": "An offence for which the police may register a case and arrest without a court warrant."},
    {"term": "Cognizance", "alias": ["cognizance"], "def": "When a court formally takes notice of an offence so that proceedings can begin."},
    {"term": "Chargesheet", "alias": ["chargesheet", "charge-sheet", "charge sheet", "final report"], "def": "The final report the police file in court after completing an investigation."},
    {"term": "Accused", "alias": [], "def": "The person charged with, or suspected of, an offence."},
    {"term": "Complainant", "alias": [], "def": "The person who reports an offence or files a complaint."},
    {"term": "Prosecution", "alias": [], "def": "The side that presents the criminal case against the accused, usually through the State."},
    {"term": "Investigating Officer", "alias": ["investigating officer"], "def": "The police officer in charge of investigating a case."},
    {"term": "Bail", "alias": ["bail"], "def": "Release of an accused person from custody while the case continues, usually on conditions such as a bond or surety."},
    {"term": "Anticipatory bail", "alias": ["anticipatory bail"], "def": "A direction that a person be released on bail if they are arrested."},
    {"term": "Surety", "alias": ["surety"], "def": "A person who promises the court that the accused will appear when required."},
    {"term": "Personal bond", "alias": ["personal bond"], "def": "A written promise by the accused to appear in court, often with an amount payable if they do not."},
    {"term": "Remand", "alias": ["remand", "remanded", "judicial custody", "police custody"], "def": "An order keeping an accused person in police or judicial custody for a period."},
    {"term": "Arrest memo", "alias": ["arrest memo"], "def": "A document recording the details of an arrest."},
    {"term": "Seizure memo", "alias": ["seizure memo", "recovery memo"], "def": "A document recording items taken by the police during an investigation."},
    {"term": "Discharge", "alias": ["discharge"], "def": "When the court finds there is not enough ground to proceed and releases the accused before trial."},
    {"term": "Framing of charges", "alias": ["charges are framed", "charge is framed", "framing of charges"], "def": "The court's formal statement of the offences the accused will be tried for."},
    {"term": "Plea", "alias": ["plea"], "def": "The accused's answer to the charge, such as pleading guilty or not guilty."},
    {"term": "Acquittal", "alias": ["acquittal", "acquitted"], "def": "A court's decision that the accused is not guilty."},
    {"term": "Conviction", "alias": ["conviction", "convicted"], "def": "A court's decision that the accused is guilty."},
    {"term": "Sentence", "alias": ["order on sentence"], "def": "The punishment ordered by the court after a conviction."},
    {"term": "Quashing", "alias": ["quash", "quashing"], "def": "Setting aside proceedings or an order so that it has no effect."},
    {"term": "Revision", "alias": ["revision petition"], "def": "A higher court's examination of a lower court's order for errors."},
    {"term": "Appeal", "alias": ["appeal memorandum", "memorandum of appeal"], "def": "A request to a higher court to review a lower court's decision."},
    {"term": "BNSS", "alias": ["BNSS"], "def": "Bharatiya Nagarik Suraksha Sanhita, 2023: the law setting out criminal procedure, which replaced the CrPC."},
    {"term": "CPC", "alias": ["CPC"], "def": "Code of Civil Procedure, 1908: the law setting out how civil cases are conducted."},
]
